    }

    private class LoadImageTask extends AsyncTask<Void, Void, Bitmap> {
        private String imageUrl;

        public LoadImageTask(String imageUrl) {
            this.imageUrl = imageUrl;
        }

        @Override
        protected Bitmap doInBackground(Void... voids) {
            try {
                return Picasso.get().load(imageUrl).get();
            } catch (IOException e) {
                e.printStackTrace();
                return null; // Return null if there's an error
            }
        }

        @Override
        protected void onPostExecute(Bitmap bitmap) {
            if (bitmap != null) {
                WallpaperManager wallpaperManager = WallpaperManager.getInstance(context);
                try {
                    wallpaperManager.setBitmap(bitmap);
                } catch (IOException ex) {
                    ex.printStackTrace();
                    // Handle error setting wallpaper
                }
            } else {
                // Handle null bitmap case (e.g., display a Toast message)
                // Example: Toast.makeText(context, "Failed to load image", Toast.LENGTH_SHORT).show();
            }
        }
    }
}
